pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Restrict to equal-length arrays to match interface expectation
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        // Adversarial helper: a callee that always succeeds when called with transferFrom selector
        vm.assume(caddress != address(0));
        // Ensure the helper is a contract with code (fuzzer cannot do this, we deploy one)
        // Deploy a minimal success callee
        SuccessCallee helper = new SuccessCallee();
        // Use helper address as the external callee
        caddress = address(helper);
        // The call must succeed (not revert)
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = true;
            // The rule: if transfer succeeded, the returned value must be true
            assertTrue(ret == true);
        } catch {
            success = false;
            // If it reverted, the property vacuously holds (no return value to compare)
            assertTrue(true);
        }
    }
}

contract SuccessCallee {
    // Fallback that returns true for any call that matches transferFrom selector
    fallback() external payable returns (bool) {
        return true;
    }
}

